const crypto = require('crypto');

// Signs a body for Convex with N8N_TO_CONVEX_SECRET (an env var, never stored
// in this workflow). Convex checks the signature and rejects timestamps older
// than 5 minutes.
function signForConvex(payload) {
  const secret = $env.N8N_TO_CONVEX_SECRET;
  if (!secret) throw new Error('N8N_TO_CONVEX_SECRET is not set');
  const body = JSON.stringify(payload);
  const timestamp = Math.floor(Date.now() / 1000).toString();
  const signature = 'v1=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + body).digest('hex');
  return { body, timestamp, signature };
}

// n8n calls this workflow when a LendLoop workflow fails (after node retries).
// It sends a short, PII-free report to Convex so admins see it in the app.
const e = $input.first().json;
const execution = e.execution || {};
const trigger = e.trigger || {};
const error = execution.error || trigger.error || {};

const report = {
  // Trigger failures have no execution id; fall back to one per workflow per minute.
  executionId: String(execution.id || ('trigger-' + (e.workflow && e.workflow.id) + '-' + Math.floor(Date.now() / 60000))),
  workflowName: String((e.workflow && e.workflow.name) || 'unknown').slice(0, 120),
  nodeName: execution.lastNodeExecuted || (error.node && error.node.name) || undefined,
  message: String(error.message || 'Unknown error').slice(0, 500),
};
console.error('[lendloop] workflow failed: ' + report.workflowName + ' at ' + report.nodeName + ': ' + report.message);

return [{ json: signForConvex(report) }];
